                    "scope": "resource",
                    "type": [
                        "string",
                        "object"
                    ],
                    "oneOf": [
                        {
                            "type": "string",
                            "markdownDescription": "Path to a `ruff.toml` or `pyproject.toml` file to use for configuration."
