                        "Use uv for formatting (requires uv >= 0.8.13)"
                    ],
                    "scope": "resource",
                    "type": "string"
                },
                "ruff.format.preview": {
                    "default": null,
                    "markdownDescription": "Enable [preview mode](https://docs.astral.sh/ruff/settings/#format_preview) for the formatter; enables unstable formatting.",
                    "scope": "resource",
                    "type": "boolean"
                },
