        "@typescript/native": "npm:typescript@^7.0.2",
        "@vscode/python-environments": "^1.0.0",
        "@vscode/test-cli": "^0.0.15",
        "@vscode/test-electron": "^3.0.0",
        "@vscode/vsce": "^3.4.2",
        "eslint": "^10.0.0",
        "eslint-import-resolver-typescript": "^4.4.5",
        "eslint-plugin-import-x": "^4.16.2",
        "glob": "^13.0.0",
        "prettier": "^3.5.3",
        "ts-loader": "^9.5.2",
        "typescript": "npm:@typescript/typescript6@^6.0.2",
        "typescript-eslint": "^8.33.0",
        "webpack": "^5.99.9",
        "webpack-cli": "^7.0.0"
    },
    "prettier": {
        "printWidth": 100,
        "tabWidth": 2,
        "trailingComma": "all"
    },
    "eslintConfig": {
        "root": true,
        "parser": "@typescript-eslint/parser",
        "parserOptions": {
            "ecmaVersion": 6,
            "sourceType": "module"
        },
        "plugins": [
            "@typescript-eslint",
            "prettier"
        ],
        "rules": {
            "prettier/prettier": "error",
            "@typescript-eslint/naming-convention": "warn",
            "@typescript-eslint/semi": "warn",
            "curly": "warn",
            "eqeqeq": [
                "warn",
                "smart"
            ],
            "no-throw-literal": "warn",
            "semi": "off"
        },
        "ignorePatterns": [
            "out",
            "dist",
            "**/*.d.ts"
        ]
    },
    "eslintIgnore": [
        "**/.nox/",
        "**/.pytest_cache/",
        "**/.ruff_cache/",
        "**/.venv/",
        "**/__pycache__/",
        "**/dist/",
        "**/node_modules/",
        "*.vsix",
        "*.pyc",
        "/bundled/libs/"
    ]
}

